// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UserTransitionCase) predicate.UserTransitionCase {
	return predicate.UserTransitionCase(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UserTransitionCase) predicate.UserTransitionCase {
	return predicate.UserTransitionCase(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UserTransitionCase) predicate.UserTransitionCase {
	return predicate.UserTransitionCase(sql.NotPredicates(p))
}
